VALUES ('214a02ec-13e4-525e-bf24-ba6fff0b46c0', '2a24a5c3-0a1e-58d5-83bc-0ae7bb9f6abe', '8ed65cb5-3fe1-510a-8107-7de4c45ca8a6', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Tax Identifier', 'Tax identifier applicable to the organization in a relevant jurisdiction. Used for tax determination, invoices, reporting, and compliance. Tax identity may vary by jurisdiction and should not replace Party identity. Supports tax-rule applicability and statutory reporting. Up to 100 characters.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
