VALUES ('1a8f82c7-d540-535b-b7d2-c9b2398199ea', 'ca09f7b1-0f0e-5071-8aa8-810eb4eef7d3', '9b544a2e-61fb-5255-a43f-1f5aae8ab071', 'Legal Entity', 'Shows one Legal Entity at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
