VALUES ('64f957df-4921-5197-a90e-0af0054d5d69', '9c88c09b-d3f6-50dd-a017-7872bac1b3fe', 'b564f0af-ccd8-5ae4-b1a8-d8f63317d257', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Id', 'The stable identity of the language record, constant even if its name or code is later corrected. Generated when the language is first loaded from the reference list; content, user preferences and translations refer to it. Must be unique: a save is rejected if another Language already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
