VALUES ('1d2632b0-0c21-502f-83bd-c2b0a0c593f1', '9c88c09b-d3f6-50dd-a017-7872bac1b3fe', 'f5dc4e21-d26d-5fda-9c24-44de3a9a5578', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Code', 'The two-letter ISO 639-1 code of the language, such as en or de. Taken from the standard; unique; used in locale settings and APIs. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Language already uses this value. Up to 2 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
