VALUES ('f676b303-6cc6-519b-ad97-b5a2bd0e9450', '7fd49185-40ed-56e1-a5da-99a398db286b', 'b402dc42-7f30-5864-9038-1ca110d61174', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Expires At', 'Optional end of the period during which the rate is valid. Used to prevent application of expired rates. When supplied, expiresAt must be later than effectiveAt. Defines the rate''s validity window for transaction and reporting calculations.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
