VALUES ('26d316ec-156e-5021-b920-5b0525f95a0f', '92dc5a1b-1e92-54b7-9ec7-2d9238d99348', 'cff32508-8ca4-52f8-8857-21f7f6023a95', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Organization', 'Optional organizational scope in which the role is recognized. Supports multi-enterprise, subsidiary, business-unit, and operating-context scenarios. Zero means global/context-independent; one means explicitly scoped to one organization. Determines which organization can use the role for applicable transactions and policies.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
