-- --------------------------------------------------------------------------
-- Lead (bus_lead)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e7bb2011-e583-5f2d-8f16-2f9a721960ce', 'Lead', 'Maintain Lead records', 'Create, find and maintain Lead records. The list shows every Lead you have access to — select a row to open it, or use New to add one. Each row is a single Lead, described by 8 fields.

Id and Lead Number are unique: no two Lead records may share the same value, and a save that would duplicate one is rejected. Lead Number and Status must be filled in before the record can be saved.

Every Lead points at Party, Customer and Opportunity. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Lead then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Lead with no rules or workflows attached is marked Final immediately.', 'target', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'bus_lead', 'Lead', 'A prospective customer or business opportunity before it has been qualified. Sales teams cannot chase every enquiry equally. A lead records a possible customer and where it came from, so the team can decide which are worth pursuing and measure how well each source performs. Created from forms, events, referrals or imports; qualified by sales; converted into a customer and opportunity or discarded; read by sales managers. A lead may identify a Party or Customer, is owned by a Party (the salesperson), and may become an Opportunity. A lead is new, goes through qualification, and ends qualified and converted into an opportunity, or disqualified or lost. A visitor who downloads a whitepaper is recorded as a lead from the website source, qualified by a call and converted to an opportunity.', 'target', 'A', FALSE, FALSE, FALSE, TRUE, 'e7bb2011-e583-5f2d-8f16-2f9a721960ce', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1adcbb51-f785-53db-998e-43c45f0748aa', 'e7bb2011-e583-5f2d-8f16-2f9a721960ce', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'Lead', 'Shows one Lead at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Party, Customer and Opportunity are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
