INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e16bf2c9-b2a0-5b9d-b4c0-df90fd15cbe3', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'lead_number', 'Lead Number', 'The reference number that identifies this prospective customer or opportunity before it has been qualified. Allocated by the system when the lead is created; unique, never reused, and quoted by sales staff in follow-up and reports.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e97a6a12-5440-5e4a-ba06-31b7c2afbbea', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'status', 'Status', 'How far the sales team has worked the lead, from first contact to conversion or loss. Moved by sales as it is qualified; a qualified lead can be converted into an opportunity, while disqualified, converted and lost leads are not worked again. Captured but not yet worked. Being assessed for fit and interest. Confirmed as a genuine prospect. Judged not to be a fit. A final state. Turned into a customer and opportunity. A final state. The prospect went elsewhere or stopped responding. A final state.', 1014, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('665f9bd6-f59b-52ea-91ad-1f7c63b379f5', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'source', 'Source', 'Where the lead came from, such as web, event or referral. Chosen at capture; used to measure which channels produce customers.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
