VALUES ('0de869e6-aa4b-5056-a355-3de472ea2971', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'party_id', 'Party', 'The person or organisation the lead is about. Linked once the prospect is identified. At most one party; a lead may be captured before the prospect is identified. Keeps contact details in one place.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
