-- --------------------------------------------------------------------------
-- Purchase Order (bus_purchase_order)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('22d6a222-cab4-568c-9e51-e8fab7aff8fa', 'Purchase Order', 'Maintain Purchase Order records', 'Create, find and maintain Purchase Order records. The list shows every Purchase Order you have access to — select a row to open it, or use New to add one. Each row is a single Purchase Order, described by 11 fields.

Id and Order Number are unique: no two Purchase Order records may share the same value, and a save that would duplicate one is rejected. Order Number, Order Date, Status and Supplier must be filled in before the record can be saved.

Every Purchase Order points at Currency, Supplier, Organization and Payment Term. Choose the linked record from the lookup on those fields rather than typing an identifier. Purchase Order Line refers back to Purchase Order, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Purchase Order then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Purchase Order with no rules or workflows attached is marked Final immediately.', 'shopping-cart', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b3e1b3c7-d599-55ad-b7dd-d7972cb9bd60', 'bus_purchase_order', 'Purchase Order', 'Represents the formal commercial procurement commitment between a buying organization and a Supplier. PurchaseOrder establishes what the Supplier is expected to provide; it is not proof that goods arrived or that later returns occurred. Purchasing, supplier management, receiving, warehouse operations, accounts payable, budgeting, inventory planning and analytics. PurchaseRequisition represents internal demand. PurchaseOrder converts approved demand into an external commitment. PurchaseOrderLine specifies the commitment. GoodsReceipt records actual receipt and acceptance. InventoryMovement records stock effects. SupplierReturn reverses eligible fulfillment. Invoice records the supplier claim. SupplierCreditNote records authorized financial reduction. Payment settles claims. Draft, approval, issuance, receipt, return, cancellation and closure are distinct stages. Financial settlement can continue after physical fulfillment or return. PurchaseOrder → GoodsReceipt → acceptance → InventoryMovement; when goods must be returned, eligible receipt → SupplierReturn → InventoryMovement reversal → SupplierCreditNote → payable reconciliation. A depot orders 100 parts, receives 96 and accepts 94. Later, three accepted parts are returned as defective. The original order and receipt remain unchanged; SupplierReturn and its inventory/credit workflows record the reversal.', 'shopping-cart', 'A', FALSE, FALSE, FALSE, TRUE, '22d6a222-cab4-568c-9e51-e8fab7aff8fa', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f2752865-c929-546d-af3e-dce3165ca211', '22d6a222-cab4-568c-9e51-e8fab7aff8fa', 'b3e1b3c7-d599-55ad-b7dd-d7972cb9bd60', 'Purchase Order', 'Shows one Purchase Order at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency, Supplier, Organization and Payment Term are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3896c796-33ee-540a-a501-e906c8661961', 'b3e1b3c7-d599-55ad-b7dd-d7972cb9bd60', 'id', 'Id', 'Immutable system identity of the purchase order. Used for procurement, receiving, invoice matching, supplier returns, audit and integrations. Identifies the order independently of orderNumber, Supplier, lines, GoodsReceipt and SupplierReturn. Stable root reference across commitment, fulfillment, reversal and closure.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6be4d63-7e1d-5654-b07c-b279ff75ce89', 'b3e1b3c7-d599-55ad-b7dd-d7972cb9bd60', 'order_number', 'Order Number', 'The human-facing procurement reference quoted by the buyer and supplier for this order. Assigned when the order is created and unique; used by buyers, suppliers, receiving, accounts payable and integrations to find it. Business reference distinct from technical purchaseOrderId. Correlates procurement activity across systems.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('96f64bb9-3b97-54fd-8356-70d29f63181e', 'b3e1b3c7-d599-55ad-b7dd-d7972cb9bd60', 'order_date', 'Order Date', 'Date and time the procurement commitment is created or issued. Supports chronology, approval, reporting and reconciliation. Distinct from requested delivery, receipt, return, invoice and payment dates. Anchors the commitment lifecycle.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cf2657f9-95cf-5d24-bbe0-09d7710f6255', 'b3e1b3c7-d599-55ad-b7dd-d7972cb9bd60', 'status', 'Status', 'Where the purchase commitment stands from draft through issue, receipt and closure. Moved by buyers, approvers and receiving; controls authorisation, issuing, cancellation and closure, and cancelled and closed are final. Being prepared by the buyer; not yet binding on anyone. Authorised internally and ready to be sent to the supplier. Issued to the supplier, who is now expected to deliver. Some of the ordered quantity has been received and accepted; the rest is outstanding. Everything required has been received and accepted. The remaining commitment has been withdrawn. A final state. Receiving and invoicing are complete. A final state. PurchaseOrder status does not prove physical receipt, supplier return or invoice settlement; those are separate facts.', 1034, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
