-- Product Category (bus_product_category)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('172599be-0168-5e37-b8bc-7a75f9a74fea', 'Product Category', 'Maintain Product Category records', 'Create, find and maintain Product Category records. The list shows every Product Category you have access to — select a row to open it, or use New to add one. Each row is a single Product Category, described by 6 fields.

Id and Code are unique: no two Product Category records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Product Category then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Product Category with no rules or workflows attached is marked Final immediately.', 'package', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a3810dd9-8fb8-5472-b7dd-390becf37c9a', 'bus_product_category', 'Product Category', 'A node in the product taxonomy that organises products for assortment, reporting, purchasing, sales, stock and analysis. Categories let people browse and report on products in groups, such as Power Tools within Hardware. They make the catalogue navigable and let rules and reports apply to a whole group instead of product by product. Maintained by product management; chosen on each product; read by navigation, reports and rules. Categories form a tree through parent and child categories, and group Products. A category is active while used, can be inactive for a time, and is retired when withdrawn. Products keep their history. "Cordless tools", a child of "Power tools", containing drills and drivers. Category create/update/retire → validate hierarchy → identify affected Products → identify dependent tax/pricing/sourcing/inventory/reporting rules → validate open workflows → activate change → preserve historical transaction classification. Code/name/description changes primarily affect presentation and integration; parent/status/semantic changes can affect Product eligibility and downstream rules and therefore require dependency analysis.', 'package', 'A', FALSE, FALSE, FALSE, TRUE, '172599be-0168-5e37-b8bc-7a75f9a74fea', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1375b554-82ed-53f7-b573-02964d99f4a1', '172599be-0168-5e37-b8bc-7a75f9a74fea', 'a3810dd9-8fb8-5472-b7dd-390becf37c9a', 'Product Category', 'Shows one Product Category at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
