INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8ba07b2e-fd5e-5cad-bacd-efbe2f6ff98c', 'a3810dd9-8fb8-5472-b7dd-390becf37c9a', 'description', 'Description', 'A description of what kinds of products belong in the category and where its boundary lies. Written by product managers when the category is created; helps people classify new products consistently and choose between similar categories.', 10, 2000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ddcb95cd-215d-5cf8-9a15-6b486f84e658', 'a3810dd9-8fb8-5472-b7dd-390becf37c9a', 'status', 'Status', 'Whether the category is in use. Set by product management; only ACTIVE categories are offered for new products. Available for classifying products. Temporarily not offered; can be reactivated. No longer used; kept for history. A final state. Status changes trigger validation of dependent Products and any rules that consume category classification.', 1030, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('40559f99-d34e-5b7e-993d-718a63e1c999', 'a3810dd9-8fb8-5472-b7dd-390becf37c9a', 'parent_category_id', 'Parent Category', 'The category that contains this one. Chosen to place the category in the tree. At most one parent; a top-level category has none. Lets reports roll up from sub-categories to broader groups.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
