INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('23fb431e-8a54-5c13-8c2e-779a2e9e4901', '1375b554-82ed-53f7-b573-02964d99f4a1', '119590c5-2699-5f81-acff-dc1c4cf57ff3', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Name', 'The name of the category as shown in navigation. Shown in catalogues and filters. Required — the record cannot be saved while this is empty. Up to 200 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
