INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7f5a0962-6c9a-517d-9c4a-1ffb0f41771d', '1375b554-82ed-53f7-b573-02964d99f4a1', '8ba07b2e-fd5e-5cad-bacd-efbe2f6ff98c', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Description', 'A description of what kinds of products belong in the category and where its boundary lies. Written by product managers when the category is created; helps people classify new products consistently and choose between similar categories. Up to 2000 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
