INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9986b500-39cb-5e83-96cf-15b3e20c173c', '1375b554-82ed-53f7-b573-02964d99f4a1', 'ddcb95cd-215d-5cf8-9a15-6b486f84e658', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Status', 'Whether the category is in use. Set by product management; only ACTIVE categories are offered for new products. Available for classifying products. Temporarily not offered; can be reactivated. No longer used; kept for history. A final state. Status changes trigger validation of dependent Products and any rules that consume category classification. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4628937e-01aa-5323-b0bf-bd7545b7bc02', '1375b554-82ed-53f7-b573-02964d99f4a1', '40559f99-d34e-5b7e-993d-718a63e1c999', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Parent Category', 'The category that contains this one. Chosen to place the category in the tree. At most one parent; a top-level category has none. Lets reports roll up from sub-categories to broader groups.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
