INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('deffc47d-af26-54d0-91ff-b41e9dbad546', 'Pricing', 'Maintain Pricing records', 'Create, find and maintain Pricing records. The list shows every Pricing you have access to — select a row to open it, or use New to add one. Each row is a single Pricing, described by 2 fields.

Id is unique: no two Pricing records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Pricing then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Pricing with no rules or workflows attached is marked Final immediately.', 'tag', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9b6e2ff4-1d54-5596-a4ea-43e6c556286c', 'bus_pricing', 'Pricing', 'A pricing definition or decision context that establishes base prices and the conditions under which they apply, before discounts, promotions, quotes or orders. Price is not a single number: it depends on product, customer, quantity and date. A pricing definition holds those conditions so orders and quotes can find the right base price and explain it. Maintained by pricing managers; looked up when quotes and orders are priced. Quotes, orders and discount rules start from the base price that this definition gives. Changes and retries preserve historical evidence and do not duplicate commercial effects. The 2026 list price for the product family in the European market.', 'tag', 'A', FALSE, FALSE, FALSE, TRUE, 'deffc47d-af26-54d0-91ff-b41e9dbad546', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bd1be46c-9c0d-5940-ab97-927da0338064', 'deffc47d-af26-54d0-91ff-b41e9dbad546', '9b6e2ff4-1d54-5596-a4ea-43e6c556286c', 'Pricing', 'Shows one Pricing at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
