VALUES ('7092122a-bab2-5012-b55e-36ac56bb929f', '22d3f694-2b02-5451-953e-11a8ad0a0937', 'daa27e09-f1ae-5b98-8fa0-413981712549', 'Promotion', 'Shows one Promotion at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
