-- --------------------------------------------------------------------------
-- Prospect (bus_prospect)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('72f2359d-70d2-5bc0-a91a-7609935a3571', 'Prospect', 'Maintain Prospect records', 'Create, find and maintain Prospect records. The list shows every Prospect you have access to — select a row to open it, or use New to add one. Each row is a single Prospect, described by 3 fields.

Id is unique: no two Prospect records may share the same value, and a save that would duplicate one is rejected. Party must be filled in before the record can be saved.

Every Prospect points at Party. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Prospect then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Prospect with no rules or workflows attached is marked Final immediately.', 'database', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a0931b7-9f89-592d-9216-0b70d128b64c', 'bus_prospect', 'Prospect', 'A potential customer that has been identified but is not yet qualified as a lead or established as a customer. A prospect is the earliest stage of a sales relationship. Recording it lets the business keep track of who it hopes to win before any qualification effort is spent, and decide later whether to promote it to a lead or drop it. Created by sales or marketing from lists, events or referrals; read by sales when deciding whom to pursue. A prospect is the sales state of one party, which holds the name and contact details. A prospect is recorded, then either qualified onward as a lead or left. Contact history is kept either way. A regional distributor met at a trade show is recorded as a prospect until a salesperson qualifies it.', 'database', 'A', FALSE, FALSE, FALSE, TRUE, '72f2359d-70d2-5bc0-a91a-7609935a3571', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7348a098-98ad-5693-b559-2e17bdeb4f72', '72f2359d-70d2-5bc0-a91a-7609935a3571', '4a0931b7-9f89-592d-9216-0b70d128b64c', 'Prospect', 'Shows one Prospect at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 1 field marked with a red asterisk (*) must have a value before Save will accept the record. Party is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
