VALUES ('1d043402-cd20-5056-8255-8a71a371edcd', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'return_number', 'Return Number', 'The number the customer and warehouse quote for the return, often called an RMA number. Identifies the return for customer service, warehouse and finance operations. Used in return authorization, transport, receiving, inspection, credit and audit. Distinct from customerReturnId, Shipment and CreditNote numbers. Provides operational reference throughout the return lifecycle.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('91a2279b-ff6c-532e-8405-b4ca3db10d63', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'status', 'Status', 'Where the return stands, from request and authorisation through transport, receipt, inspection and completion. Moved by customer service and the warehouse; it controls what may happen next but does not itself change stock or invoices. Being prepared; not yet authorised. Approved by the seller; the customer may send the goods back. The goods are on their way back. The goods have arrived at the returns location. Waiting for the returned goods to be inspected. Each line has a decision: restock, quarantine, repair or scrap. All physical and financial effects are done. Withdrawn before completion; no effects remain. Held because something went wrong, such as damage or a missing item, and needs a decision. Controls progression through transport, receipt, inspection, disposition, inventory and financial adjustment. Return status does not itself change inventory or invoice balances. Coordinates dependent return workflows; CreditNote posting is a separate financial state.', 1007, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f0f27aab-9134-5cb9-beb2-3fa6c5a09129', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'return_date', 'Return Date', 'Date and time the return event was initiated or recognized. Anchors return chronology independently from receipt and credit-note dates. Used for service metrics, logistics, audit and policy evaluation. Distinct from shipment, receipt, disposition and CreditNote dates. Provides temporal context for return authorization and processing.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dbde9e34-0c00-565c-bc24-af74a7f8713a', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'reason_code', 'Reason Code', 'Business reason supplied for the customer return. Explains why goods or services are being returned. Used for approval, quality, analytics, warranty and customer service. May differ from the financial CreditNote.reasonCode. Supports eligibility and policy determination.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8539ed4e-97e2-52f5-8350-90af52015d60', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'notes', 'Notes', 'Free-text remarks about the return, such as damage seen on arrival or what the customer said. Written by customer service or warehouse staff for colleagues and audit; the facts that matter are held in structured fields. Captures information not represented by structured return fields. Notes supplement but do not replace structured evidence. Provides contextual information during exception handling.', 10, 2000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f6eb8325-8ef3-5bcd-8beb-c574e2d863f0', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'customer_id', 'Customer', 'Customer requesting or receiving the return process. Identifies the party associated with the reverse transaction. Supports authorization, logistics, credit and customer service. Supplies party eligibility and financial context.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
