-- --------------------------------------------------------------------------
-- Brand (bus_brand)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ef65551b-e8c8-51ae-b6d1-597b9350d310', 'Brand', 'Maintain Brand records', 'Create, find and maintain Brand records. The list shows every Brand you have access to — select a row to open it, or use New to add one. Each row is a single Brand, described by 4 fields.

Id and Code are unique: no two Brand records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Product refers back to Brand, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Brand then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Brand with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6239192d-6b77-55e0-81b0-b0614027ceaa', 'bus_brand', 'Brand', 'Governed product brand reference master. Brand describes commercial/manufacturer identity; it is distinct from ProductCategory taxonomy and Product identity. PIM, catalog, sourcing, sales, e-commerce, service and analytics. Products and variants reference Brand; category remains independent classification. Active → inactive → active or retired. Lifecycle/name changes update future catalog/master usage while preserving historical references.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'ef65551b-e8c8-51ae-b6d1-597b9350d310', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ca798427-a2a4-5fa1-b7a8-152f40786b3f', 'ef65551b-e8c8-51ae-b6d1-597b9350d310', '6239192d-6b77-55e0-81b0-b0614027ceaa', 'Brand', 'Shows one Brand at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eb79a8d5-f29c-5bd0-a0bc-327a8e861b9d', '6239192d-6b77-55e0-81b0-b0614027ceaa', 'id', 'Id', 'The identity of the brand, stable when its name or code is revised. Identifies the brand independently of display-name changes. PIM, catalog, commerce and reporting. Referenced by Products/Variants.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3952c2b5-7e16-5541-a3e2-9812ccb539b2', '6239192d-6b77-55e0-81b0-b0614027ceaa', 'code', 'Code', 'The short unique code identifying the brand across catalogue, sourcing and integration systems. Assigned by master-data governance when the brand is created; used as the stable key when products and feeds name the brand. Stable business/integration identifier. Unique in brand master.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('abaa9d82-07be-51ac-9f06-f92f38cbccd0', '6239192d-6b77-55e0-81b0-b0614027ceaa', 'name', 'Name', 'The brand''s display name as customers and buyers know it, such as the manufacturer''s trading name. Shown on catalogue pages, documents and search results, and used to group sales and sourcing reports by brand. Customer/supplier-facing market identity. Presentation can change without changing brand identity.', 10, 300, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c8164ff0-23e2-5705-b786-0744e5ed6b0e', '6239192d-6b77-55e0-81b0-b0614027ceaa', 'status', 'Status', 'Whether the brand is in use, paused, or withdrawn from the catalogue. Set by master-data governance; only active brands are offered for new products, and retired ones are kept for history. In use and available for assignment to products. Temporarily not offered, for example while a licence is renegotiated; it can be reactivated. No longer used; kept so historical sales and catalogue records remain accurate. A final state. Controls future assignment/use. Historical product/transaction references remain valid.', 1002, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ea125054-e2ad-5d45-8abf-c5e6739c679d', 'ca798427-a2a4-5fa1-b7a8-152f40786b3f', 'eb79a8d5-f29c-5bd0-a0bc-327a8e861b9d', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Id', 'The identity of the brand, stable when its name or code is revised. Identifies the brand independently of display-name changes. PIM, catalog, commerce and reporting. Referenced by Products/Variants. Must be unique: a save is rejected if another Brand already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('caf14d54-d952-5e3d-8b13-46e0350c43a8', 'ca798427-a2a4-5fa1-b7a8-152f40786b3f', '3952c2b5-7e16-5541-a3e2-9812ccb539b2', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Code', 'The short unique code identifying the brand across catalogue, sourcing and integration systems. Assigned by master-data governance when the brand is created; used as the stable key when products and feeds name the brand. Stable business/integration identifier. Unique in brand master. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Brand already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4519844b-64b8-5409-9220-f578d3116b86', 'ca798427-a2a4-5fa1-b7a8-152f40786b3f', 'abaa9d82-07be-51ac-9f06-f92f38cbccd0', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Name', 'The brand''s display name as customers and buyers know it, such as the manufacturer''s trading name. Shown on catalogue pages, documents and search results, and used to group sales and sourcing reports by brand. Customer/supplier-facing market identity. Presentation can change without changing brand identity. Required — the record cannot be saved while this is empty. Up to 300 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('69a9489e-41d0-5853-94f6-70370ba7764a', 'ca798427-a2a4-5fa1-b7a8-152f40786b3f', 'c8164ff0-23e2-5705-b786-0744e5ed6b0e', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Status', 'Whether the brand is in use, paused, or withdrawn from the catalogue. Set by master-data governance; only active brands are offered for new products, and retired ones are kept for history. In use and available for assignment to products. Temporarily not offered, for example while a licence is renegotiated; it can be reactivated. No longer used; kept so historical sales and catalogue records remain accurate. A final state. Controls future assignment/use. Historical product/transaction references remain valid. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
