INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8283036f-c1e4-5d33-84f6-e9590775c34f', 'Customer Return Line Disposition', 'Maintain Customer Return Line Disposition records', 'Create, find and maintain Customer Return Line Disposition records. The list shows every Customer Return Line Disposition you have access to — select a row to open it, or use New to add one. Each row is a single Customer Return Line Disposition, described by 6 fields.

Id and Code are unique: no two Customer Return Line Disposition records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Customer Return Line Disposition then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Customer Return Line Disposition with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ef4cc9b0-6d47-5383-b5e5-3de64a797a67', 'bus_customer_return_line_disposition', 'Customer Return Line Disposition', 'The values of customer return line disposition, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '8283036f-c1e4-5d33-84f6-e9590775c34f', 'U', TRUE, 'system', 'system', NOW(), NOW())
