-- --------------------------------------------------------------------------
-- Sales Order Line (bus_sales_order_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0a9223c0-0618-5b2d-9114-aec39ccaba55', 'bus_sales_order_line', 'Sales Order Line', 'One product or service on a sales order, with its quantity, price, discount, tax and fulfilment progress. The line is the precise commitment: what, how many, at what price from which source. It tracks how much has been reserved, shipped and billed, so each line can be followed to completion and the price the customer agreed is preserved. Created with the order; updated as stock is allocated and shipped; read by warehouse and billing. A line belongs to one order and product, and is matched by shipments, reservations and invoice lines. A line follows its order. Its allocated and fulfilled quantities grow as stock is reserved and shipped. Line 2 of SO-10482 orders 40 units at 18.50; 25 are allocated and 15 shipped. Confirmed order line → availability → InventoryReservation → pick/issue → Shipment → accepted fulfillment → quantityFulfilled → billing. Cancellation/reduction releases or reconciles reservations and open shipments before changing remaining demand. Master-data changes trigger controlled revalidation. quantityAllocated follows reservation events; quantityFulfilled follows accepted fulfillment events; SalesOrder status follows line states; InvoiceLine follows billing policy; Product/UOM/pricing changes affect future or explicitly revalidated open work only. Reservation, fulfillment, cancellation and billing allocation require concurrency control and idempotency to prevent double allocation, double fulfillment or double billing.', 'shopping-cart', 'A', FALSE, FALSE, FALSE, TRUE, '69e23ac0-6532-503a-886e-617bcb0772bc', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6e53987-25c6-552f-be47-7a2515aadec7', '69e23ac0-6532-503a-886e-617bcb0772bc', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'Sales Order Line', 'Shows one Sales Order Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 8 fields marked with a red asterisk (*) must have a value before Save will accept the record. Unit Of Measure, Sales Order and Product are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f64ec866-1f99-5daf-ad09-5a170d79cb72', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'id', 'Id', 'The identity of the line, constant for its life. Generated on creation; shipments and invoices refer to it. Referenced when delivery and billing are matched.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('31837073-0379-5919-a075-e011a576492d', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'line_number', 'Line Number', 'The position of the line on the order. Assigned in sequence; used to refer to the line. Read with the order number to name a line.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('593aa3f3-0a7c-52c5-a733-ccc5b5a60299', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'quantity', 'Quantity', 'The number of units of the product or service the customer ordered on this line. Entered by sales; stock allocation, shipment and invoicing are all measured against it, and it drives the line amount. Compared with allocated and fulfilled quantity.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d954fdfb-7d93-5e1e-86f9-4a5bd598e8f1', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'quantity_fulfilled', 'Quantity Fulfilled', 'How many units of the ordered quantity have been shipped or delivered so far. Increased by each shipment and never above the ordered quantity; the line is fulfilled when it equals the quantity. Reaching the ordered quantity completes the line.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4f6c13b5-e6fc-5819-bdca-97f516588b40', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'quantity_allocated', 'Quantity Allocated', 'The quantity of stock reserved for the line. Increased by reservations; read by the warehouse. Compared with the quantity still to ship.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('932cab18-e594-5e7f-bcf7-db7d48c01bea', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'unit_price', 'Unit Price', 'Agreed transaction-time price per unit including currency. Order valuation, invoicing, margin, credit and reconciliation. Must align with SalesOrder currency and UnitOfMeasure pricing basis. Authoritative commercial price for downstream billing unless controlled repricing occurs.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3074e11b-be1f-5fba-ae3b-8b782ef0edeb', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'discount_amount', 'Discount Amount', 'The money taken off this line by the discount agreed when the order was taken. Set when the price is determined and approved under discount policy; subtracted in the line amount and shown on invoices. Currency must match order pricing currency. Preserves the concession actually granted rather than relying on current DiscountRule.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f7c0ecbc-24c3-52e2-963b-ba96e9ad98fc', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'tax_amount', 'Tax Amount', 'Tax determined for the order line when tax is calculated at order stage. Supports order and invoice reconciliation. Determination may depend on Product, Customer, address, location, date and TaxRule. Preserves tax evidence when the order commits to a tax amount.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('032a08f7-4661-54cf-8805-8d223c86d6ed', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'line_amount', 'Line Amount', 'The net value of the line after quantity, price, discount and tax have been worked out. Calculated by the system rather than typed; summed into order totals, invoiced, and used for credit checks and reporting. Must reconcile with pricing, discount, tax and rounding policy. Financial baseline for downstream billing and reconciliation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('58a866f9-0ae7-50a8-90f4-6773d1f70ce1', '0a9223c0-0618-5b2d-9114-aec39ccaba55', 'price_source', 'Price Source', 'Where the price on the line came from. Set when the price is determined. Lets a disputed price be traced. Taken from the price list. Taken from a contract with the customer. Taken from a standing customer agreement. Taken from an accepted quotation. Entered by the salesperson. Set by a promotion. Determined some other way.', 1037, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
