VALUES ('a110a46a-1362-5224-b798-d885fb58944e', 'd6e53987-25c6-552f-be47-7a2515aadec7', '593aa3f3-0a7c-52c5-a733-ccc5b5a60299', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Quantity', 'The number of units of the product or service the customer ordered on this line. Entered by sales; stock allocation, shipment and invoicing are all measured against it, and it drives the line amount. Compared with allocated and fulfilled quantity. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
