-- --------------------------------------------------------------------------
-- Purchase Order Line (bus_purchase_order_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5d84b4c1-d962-555b-9c69-c9434227b6f0', 'bus_purchase_order_line', 'Purchase Order Line', 'One item ordered on a purchase order, with the quantity, price and the progress of receipt, invoicing and return. The line is where the commitment is made precise: which product, how many, at what price and from what source. It keeps the price as agreed at the time and tracks what has since arrived, been accepted, returned and is still owed, so the order''s completion can be judged line by line. Created with the order, from a requisition or quotation line; updated as goods arrive; read by receiving, accounts payable and buyers. A line belongs to one order and product, may come from a quotation or requisition line, and is matched by receipt, invoice and return lines. A line follows its order: open until fully received, then settled. Its quantities change only through receipts and returns. Line 2 of PO-5120 orders 400 bolts at 0.35 each; 250 have been received and 150 are outstanding. Pricing → commitment → receipt → acceptance → InventoryMovement; if goods are returned, eligible accepted quantity → SupplierReturnLine → InventoryMovement reversal → SupplierCreditNoteLine. Historical commitment remains unchanged.', 'shopping-cart', 'A', FALSE, FALSE, FALSE, TRUE, '22d6a222-cab4-568c-9e51-e8fab7aff8fa', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('43007c54-21c9-5cbc-8f8c-b0c13a48c1fa', '22d6a222-cab4-568c-9e51-e8fab7aff8fa', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'Purchase Order Line', 'Shows one Purchase Order Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 10 fields marked with a red asterisk (*) must have a value before Save will accept the record. Unit Of Measure, Purchase Order and Product are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
