VALUES ('3fd57d02-76d2-5aa6-9bab-4ba38897a721', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'line_amount', 'Line Amount', 'The value of the line: quantity times unit price. Calculated; summed into the order total. Matched against the invoiced amount.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
