INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bf78ebed-b2ea-596f-b65f-9b70802d4b5f', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'received_quantity', 'Received Quantity', 'The total quantity of this line that has physically arrived from the supplier so far, accepted or not. Increased by goods receipt lines; compared with the ordered quantity to show what is outstanding, and never negative. Compared with accepted quantity to find rejections.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
