INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('52df0b3e-2324-504e-82e3-65e945e72917', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'accepted_quantity', 'Accepted Quantity', 'The quantity received and accepted after inspection. Increased as receipts are accepted; invoicing is matched to it. Never more than the received quantity.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
