INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c297f558-dc75-5821-8c5e-c20edfd9ae86', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'returned_quantity', 'Returned Quantity', 'The total quantity of this line that has been sent back to the supplier after receipt. Increased by supplier return lines; must not exceed what was accepted unless an exception is authorised, and does not reopen the original commitment. Reduces the accepted quantity that is payable.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5595a447-0c68-5af5-9b2a-b524ef85267e', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'outstanding_quantity', 'Outstanding Quantity', 'The quantity still to be delivered. Calculated from ordered, received and returned; read by expediters. Reaches zero when the line is fully delivered.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
