INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d540b936-87b7-5041-be08-8c439a2322d6', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'price_source', 'Price Source', 'Where the unit price on this line came from, such as a price list, a contract or a buyer''s manual entry. Recorded when the price is determined; supports audit, spend analysis and supplier negotiation by showing which agreement justified the price. Taken from the supplier''s published price list in force at the time. Taken from a negotiated contract with the supplier. Taken from a standing supplier agreement covering repeat purchases. Taken from a supplier quotation that the buyer accepted. Typed in by the buyer without a supporting agreement. Determined in some other way not covered by the listed sources. Does not replace transaction-time unitPrice. Explains price determination.', 1033, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0bb4ba3f-5d50-51a9-a1d6-7c691f3de3bd', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'price_determined_at', 'Price Determined At', 'The date and time at which the price on this line was fixed. Recorded when the price is determined; lets later audits tell which effective-dated price applied even after price lists change. Distinct from PurchaseOrder creation time. Anchors commercial pricing evidence.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('574f3c1b-db0f-59ce-9c81-5662bffa7df5', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'unit_of_measure_id', 'Unit Of Measure', 'The unit the quantity is expressed in. Defaults to the product''s purchasing unit. At most one unit; empty uses the product''s default. Defines how quantity is interpreted. Must reconcile with receiving and return conversions.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
