VALUES ('3ef0dfcc-65a9-521d-ab01-6eb96fdeae89', '5d84b4c1-d962-555b-9c69-c9434227b6f0', 'purchase_order_id', 'Purchase Order', 'The purchase order this line belongs to. Set when the line is added. Exactly one order; a line cannot stand alone. Supplies supplier, organization, currency and lifecycle context. Controls commitment and closure.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
