-- --------------------------------------------------------------------------
-- Quotation Line (bus_quotation_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('299f2906-5bf5-5416-941b-3f49598b9107', 'bus_quotation_line', 'Quotation Line', 'Preserves the commercial terms offered to a customer and the evidence needed when those terms become an order. QuotationLine is a transaction-time commercial snapshot, not merely a pointer to current pricing master data. Quotation, negotiation, approval, sales conversion, margin analysis, audit, and customer communication. Product and UnitOfMeasure provide master context; the Quotation supplies customer and currency context; pricing sources explain determination but do not replace the stored effective price. Product/customer/pricing inputs → price determination → QuotationLine snapshot → quotation approval → optional conversion to SalesOrderLine. Master-data changes affect future quotations unless an explicit repricing workflow is invoked. Draft → priced → approved/issued → accepted/rejected/expired. Once accepted, commercial evidence is preserved. A customer quotation is priced at USD 125 per unit using a customer agreement. The agreement later changes to USD 130. An accepted quotation remains at USD 125 unless the customer explicitly accepts a controlled repricing/revision.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'be0b3b38-2cf4-5cb9-b4da-8507f69b0c6b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('381729f6-0207-554e-9a89-1d273a0a9c22', 'be0b3b38-2cf4-5cb9-b4da-8507f69b0c6b', '299f2906-5bf5-5416-941b-3f49598b9107', 'Quotation Line', 'Shows one Quotation Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Quotation, Product and Unit Of Measure are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d18b85e-d0df-5f8a-9a37-4117dbf746f1', '299f2906-5bf5-5416-941b-3f49598b9107', 'id', 'Id', 'The identity of the line, constant for its life. Generated on creation; the order line made from it refers to it. Referenced when the quote is converted.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0d8c855a-06b1-5951-8d20-4e6ae1ea7b12', '299f2906-5bf5-5416-941b-3f49598b9107', 'line_number', 'Line Number', 'The position of the line on the quotation. Assigned in sequence; used to refer to the line. Read with the quotation number to name the line.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f2762341-45ed-5e5c-9594-1b94d00858a5', '299f2906-5bf5-5416-941b-3f49598b9107', 'quantity', 'Quantity', 'The number of units of the product or service offered to the customer on this line. Entered by the salesperson, multiplied by the unit price to give the line value, and carried onto the order if the customer accepts. Carried to the order line if accepted.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8954e75a-c5b8-502d-9113-dca050e56d54', '299f2906-5bf5-5416-941b-3f49598b9107', 'unit_price', 'Unit Price', 'Transaction-time quoted price per unit, including its currency. Used for quotation valuation and, when accepted, as source evidence for downstream SalesOrder pricing. Must be interpreted with the quotation currency and UnitOfMeasure. Price determination may source a current price rule, but the accepted quotation retains this effective price.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e02d067e-8f0f-5070-bc62-2ee864cd9deb', '299f2906-5bf5-5416-941b-3f49598b9107', 'amount', 'Amount', 'Calculated gross commercial value of the quotation line before any separately represented adjustments. Supports quotation totals and conversion validation. Currency must match unitPrice and the quotation currency under the quotation''s pricing policy. Provides a reproducible quoted amount.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('be1cea00-b17b-5698-b366-b80defef241d', '299f2906-5bf5-5416-941b-3f49598b9107', 'discount_amount', 'Discount Amount', 'Transaction-time discount amount granted on the quoted line. Preserves the commercial concession used to derive the net amount. Must use the quotation currency. Prevents later DiscountRule changes from rewriting an accepted quotation.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('445360bb-6046-5b1e-9944-fc9132a07438', '299f2906-5bf5-5416-941b-3f49598b9107', 'price_source', 'Price Source', 'Taken from the price list. Taken from a contract with the customer. Taken from a standing agreement with the customer. Entered by the salesperson. Set by a promotion. Determined some other way. Records the business source used to determine the quoted price. Supports audit, margin analysis, pricing explanation, and downstream conversion. Source metadata does not replace the transaction-time unitPrice. Explains why the quoted price was selected.', 1035, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a86c38f2-cfea-521a-9a9f-8e2ad272ef49', '299f2906-5bf5-5416-941b-3f49598b9107', 'price_determined_at', 'Price Determined At', 'Timestamp at which the quoted price was determined. Supports effective-dated pricing audit and reproducibility. Distinct from quotation creation time when pricing is recalculated or manually overridden. Provides temporal evidence for price determination.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b7e4cc5c-e9cd-557f-b7ed-688877ae57f9', '299f2906-5bf5-5416-941b-3f49598b9107', 'description', 'Description', 'A description of what is offered on the line. Defaults to the product description; edited for services or special terms. Printed on the quotation.', 10, 1000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
