INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e624d60a-e7aa-5947-befd-8314d01ff6c3', '299f2906-5bf5-5416-941b-3f49598b9107', 'quotation_id', 'Quotation', 'Links a quotation line to quotation, the quotation it relates to. Chosen from the existing quotation records when the quotation line is created or edited. A quotation line has exactly one quotation in this role. Lets the quotation line be found from, and reported with, its quotation.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
