-- --------------------------------------------------------------------------
-- Customer Return Line (bus_customer_return_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('758fa933-52cf-51ce-ba65-d591ca9f52f3', 'bus_customer_return_line', 'Customer Return Line', 'Quantity-level return evidence connecting returned goods to original fulfillment, disposition, inventory and financial adjustment. CustomerReturnLine explains exactly what quantity came back and what happened to it. It does not itself move inventory or issue a credit. Reverse logistics, quality, inventory, customer service, credit processing and audit. SalesOrderLine identifies the original commitment; InvoiceLine identifies the financial claim; InventoryMovement records physical consequences; CreditNoteLine records the financial consequence. Return authorization → returned quantity → receipt → inspection → disposition → restock/quarantine/repair/scrap → credit eligibility → CreditNoteLine → CreditNote posting. Each consequence is posted through its authoritative workflow. Pending → inspected → dispositioned → posted/completed, with controlled correction if necessary. Changes to source fulfillment, invoice, product, UOM or policy revalidate open return lines. Posted physical or financial effects are corrected through compensating events. Five units returned: three restocked, one quarantined and one scrapped. Only three generate unrestricted positive inventory movement. An approved USD 590 credit becomes a CreditNoteLine and is posted through CreditNote without changing the original InvoiceLine.', 'user-round', 'A', FALSE, FALSE, FALSE, TRUE, 'd531139a-3660-5f8e-8d4c-0eaba7bc70d9', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('231c84f1-2c33-545d-b097-1dc68734ed6c', 'd531139a-3660-5f8e-8d4c-0eaba7bc70d9', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'Customer Return Line', 'Shows one Customer Return Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 9 fields marked with a red asterisk (*) must have a value before Save will accept the record. Customer Return and Sales Order Line are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f4f12603-014e-5393-ad3b-8f6588ed6bab', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'id', 'Id', 'The identity of the return line. Identifies one returned-item detail independently of the parent return, source order line, inventory movement or credit note. Used for quantity reconciliation, inventory posting, credit calculation and audit. Stable bridge identity across reverse-fulfillment and financial workflows. Carries source quantity through receipt, disposition and downstream credit processing.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f6627544-b86d-5fdd-a6b7-12a5b00fe37f', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'line_number', 'Line Number', 'Sequence number of the line within the CustomerReturn. Identifies the line for operational documents and reconciliation. Used in return documents, receiving and audit. Unique within the parent return and independent of SalesOrderLine or InvoiceLine numbering. Supports deterministic return reconstruction.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('af9845f4-cb95-53bd-9517-236fe8dc5634', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'quantity_returned', 'Quantity Returned', 'Quantity physically or contractually returned for this line. Establishes the quantity subject to inspection and disposition. Used for return validation, inventory and financial eligibility. Must be supported by prior fulfillment evidence and cannot automatically become inventory or credit. Feeds disposition quantities and potential credit calculation.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('020f40f6-c136-5561-8783-7d0e9f30a9c2', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'quantity_restocked', 'Quantity Restocked', 'How many returned units passed inspection and may go back into unrestricted, saleable stock. Entered at disposition by the warehouse; it alone drives the positive stock movement, and it is part of the quantity returned. Represents returned goods approved to re-enter unrestricted inventory. Must be a component of quantityReturned and is the only disposition component eligible for unrestricted stock. Creates the inventory consequence after disposition approval.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('98ff4f9a-2959-5f3b-a790-980781eee1b7', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'quantity_quarantined', 'Quantity Quarantined', 'How many returned units are held in restricted stock until further inspection or controlled handling. Entered at disposition by quality staff; it never adds to available stock, and it is part of the quantity returned. Represents returned goods requiring further inspection or controlled handling. Does not increase unrestricted available inventory. Drives restricted disposition workflow.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e4854ce6-8787-57ea-8890-d48664732368', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'quantity_to_repair', 'Quantity To Repair', 'How many returned units are sent for repair or refurbishment before any decision on their stock. Entered at disposition; it may raise a repair work order and adds nothing to unrestricted stock, and it is part of the quantity returned. Represents goods that require a repair process before any future stock disposition. Does not directly create unrestricted stock. Drives repair workflow and later disposition.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fdab647a-ef72-5715-a32e-985251315514', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'quantity_scrapped', 'Quantity Scrapped', 'How many returned units are approved for scrap or disposal and will never return to saleable stock. Entered at disposition by the warehouse; it feeds disposal and inventory write-off, and it is part of the quantity returned. Represents returned goods that will not return to saleable inventory. Does not increase unrestricted available inventory. Drives authorized disposal and inventory adjustment.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('98470b43-6927-56f6-829a-554e3de5bfad', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'disposition', 'Disposition', 'No decision has been made yet. The goods are put back into saleable stock. The goods are held apart pending a quality decision. The goods are sent for repair. The goods are written off and disposed of. Different quantities of the line have different decisions. Physical disposition assigned after inspection of returned goods. Determines what operational path the returned quantity follows. Drives inventory, quality, repair and disposal processing. Distinct from return reason and financial credit reason. Determines authoritative InventoryMovement or downstream workflow.', 1006, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('88146867-f07d-505e-92bf-67560b59bada', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'approved_credit_amount', 'Approved Credit Amount', 'Maximum financial credit approved for this return line under applicable policy. Provides the financial eligibility basis consumed by CreditNoteLine; it is not itself a posted credit. Supports customer credit calculation, approval and audit. Must reconcile with original InvoiceLine pricing/tax evidence and must not mutate the invoice. Limits return-based CreditNoteLine credit unless a separate authorized adjustment applies.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('27d8c224-b2da-5483-9b76-6c51a041decd', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'customer_return_id', 'Customer Return', 'Parent return containing this returned quantity detail. Establishes the authorization and lifecycle context. Supports return processing and completion. Parent lifecycle coordinates this line''s processing.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c88ea533-1b58-5832-a611-b9b2bbfeddac', '758fa933-52cf-51ce-ba65-d591ca9f52f3', 'sales_order_line_id', 'Sales Order Line', 'Original sales commitment line against which the return is validated. Identifies the demand and fulfillment quantity being reversed. Supports eligibility and fulfillment reconciliation. Supplies original ordered and fulfilled context.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
